def copiar_resolucao_para_material(apps, schema_editor):
    """A aula passa a ter um único arquivo: o material resolvido.

    Onde existia uma resolução, ela é a versão resolvida — então passa a
    ocupar o campo material antes de o campo resolucao ser removido.
    """
    Aula = apps.get_model('core', 'Aula')
    for aula in Aula.objects.exclude(resolucao='').exclude(resolucao__isnull=True):
        aula.material = aula.resolucao
        aula.save(update_fields=['material'])


